SELECT w.w_warehouse_name, cd.cd_gender, SUM(ss.ss_net_profit) AS profit_sum, SUM(cr.cr_net_loss) AS loss_sum, SUM(ss.ss_net_profit) - SUM(cr.cr_net_loss) AS net_gain, ROW_NUMBER() OVER (PARTITION BY w.w_warehouse_name ORDER BY SUM(ss.ss_net_profit) DESC) AS profit_rank, CASE WHEN SUM(cr.cr_net_loss) > 5000 THEN 'Elevated Loss' ELSE 'Moderate Loss' END AS loss_category FROM warehouse w LEFT JOIN catalog_returns cr ON cr.cr_warehouse_sk = w.w_warehouse_sk LEFT JOIN customer_demographics cd ON cr.cr_refunded_cdemo_sk = cd.cd_demo_sk LEFT JOIN store_sales ss ON ss.ss_cdemo_sk = cd.cd_demo_sk WHERE cr.cr_return_quantity > 0 GROUP BY w.w_warehouse_name, cd.cd_gender HAVING SUM(ss.ss_net_profit) > 1000 OR SUM(cr.cr_net_loss) > 1000 ORDER BY net_gain ASC LIMIT 10
